using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace DeepDwarf
{
    /// <summary>Monospace 5x7 bitmap font with Cyrillic, generated by Tools/generate_art.py.</summary>
    public static class PixelFont
    {
        // Must match FONT_CHARS in Tools/generate_art.py.
        const string Chars = "АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯDFGIJLNQRSUVWZ0123456789.,:!?-+/%()>x";
        // Latin capitals drawn the same as a Cyrillic letter share its glyph.
        const string LatinTwins = "ABCEHKMOPTXY";
        const string CyrillicTwins = "АВСЕНКМОРТХУ";
        public const int CellWidth = 6;
        public const int CellHeight = 8;
        const int GlyphWidth = 5;
        const int GlyphHeight = 7;
        const int PerRow = 16;

        static Dictionary<char, int> map;
        static Texture2D texture;

        public static Texture2D Texture
        {
            get
            {
                if (texture == null) texture = Resources.Load<Texture2D>("Art/font");
                return texture;
            }
        }

        public static bool TryGetUv(char c, out Vector2 min, out Vector2 max)
        {
            if (map == null)
            {
                map = new Dictionary<char, int>();
                for (int i = 0; i < Chars.Length; i++) map[Chars[i]] = i;
                for (int i = 0; i < LatinTwins.Length; i++) map[LatinTwins[i]] = map[CyrillicTwins[i]];
            }
            min = max = Vector2.zero;
            if (!map.TryGetValue(c, out int index) && !map.TryGetValue(char.ToUpperInvariant(c), out index))
                return false;
            float w = Texture.width, h = Texture.height;
            int cx = index % PerRow * CellWidth, cy = index / PerRow * CellHeight;
            min = new Vector2(cx / w, 1f - (cy + GlyphHeight) / h);
            max = new Vector2((cx + GlyphWidth) / w, 1f - cy / h);
            return true;
        }
    }

    /// <summary>UI text drawn from the bitmap font. Works the same on every platform.</summary>
    [RequireComponent(typeof(CanvasRenderer))]
    public class PixelLabel : MaskableGraphic
    {
        string text = "";
        int pixelSize = 2;
        TextAnchor alignment = TextAnchor.MiddleLeft;
        readonly List<string> lines = new List<string>();
        static readonly Color32 ShadowColor = new Color32(16, 12, 20, 255);

        public override Texture mainTexture => PixelFont.Texture;

        public string Text
        {
            get => text;
            set
            {
                if (text == value) return;
                text = value ?? "";
                SetVerticesDirty();
            }
        }

        public void Setup(int size, TextAnchor anchor)
        {
            pixelSize = size;
            alignment = anchor;
            raycastTarget = false;
            SetVerticesDirty();
        }

        protected override void OnPopulateMesh(VertexHelper vh)
        {
            vh.Clear();
            Rect rect = rectTransform.rect;
            float advance = PixelFont.CellWidth * pixelSize;
            float lineHeight = (PixelFont.CellHeight + 1) * pixelSize;
            WrapLines(Mathf.Max(1, Mathf.FloorToInt((rect.width + pixelSize) / advance)));

            float total = lines.Count * lineHeight - 2 * pixelSize;
            float top = rect.yMax;
            if (alignment == TextAnchor.MiddleLeft || alignment == TextAnchor.MiddleCenter || alignment == TextAnchor.MiddleRight)
                top = rect.center.y + total / 2f;

            for (int i = 0; i < lines.Count; i++)
            {
                string line = lines[i];
                float width = line.Length * advance - pixelSize;
                float x = rect.xMin;
                if (alignment == TextAnchor.MiddleCenter || alignment == TextAnchor.UpperCenter) x = rect.center.x - width / 2f;
                else if (alignment == TextAnchor.MiddleRight || alignment == TextAnchor.UpperRight) x = rect.xMax - width;
                float y = top - i * lineHeight;
                DrawLine(vh, line, x + pixelSize, y - pixelSize, ShadowColor, advance);
                DrawLine(vh, line, x, y, color, advance);
            }
        }

        void DrawLine(VertexHelper vh, string line, float x, float top, Color32 tint, float advance)
        {
            float w = 5 * pixelSize, h = 7 * pixelSize;
            for (int c = 0; c < line.Length; c++, x += advance)
            {
                if (line[c] == ' ' || !PixelFont.TryGetUv(line[c], out var min, out var max)) continue;
                int start = vh.currentVertCount;
                vh.AddVert(new Vector3(x, top - h), tint, new Vector4(min.x, min.y));
                vh.AddVert(new Vector3(x, top), tint, new Vector4(min.x, max.y));
                vh.AddVert(new Vector3(x + w, top), tint, new Vector4(max.x, max.y));
                vh.AddVert(new Vector3(x + w, top - h), tint, new Vector4(max.x, min.y));
                vh.AddTriangle(start, start + 1, start + 2);
                vh.AddTriangle(start + 2, start + 3, start);
            }
        }

        void WrapLines(int maxChars)
        {
            lines.Clear();
            foreach (string paragraph in text.Split('\n'))
            {
                string current = "";
                foreach (string word in paragraph.Split(' '))
                {
                    string candidate = current.Length == 0 ? word : current + " " + word;
                    if (candidate.Length > maxChars && current.Length > 0)
                    {
                        lines.Add(current);
                        current = word;
                    }
                    else
                    {
                        current = candidate;
                    }
                }
                lines.Add(current);
            }
        }
    }
}
